# worker.py
import os
import time

from celery import Celery

app = Celery(
    "ml_tasks",
    broker=os.getenv("CELERY_BROKER_URL", "redis://localhost:6379/0"),
    backend=os.getenv("CELERY_RESULT_BACKEND", "redis://localhost:6379/0"),
)

@app.task(name="predict_task")
def predict_task(texte: str) -> dict:
    time.sleep(int(os.getenv("MODEL_LATENCY", "5")))     # modèle lourd simulé
    return {"texte": texte, "prediction": 42}

# api.py
from celery.result import AsyncResult
from fastapi import FastAPI

api = FastAPI()

@api.post("/predict", status_code=202)
def soumettre(texte: str):
    return {"task_id": predict_task.delay(texte).id}

@api.get("/tasks/{task_id}")
def statut(task_id: str):
    res = AsyncResult(task_id, app=app)
    return {"statut": res.status, "resultat": res.result if res.successful() else None}
